   170|export function initializeMemory(): void {
   171|  if (initialized) return;
   172|  initialized = true;
   173|
   174|  const now = new Date().toISOString();
   175|  for (const seed of COMPANY_MEMORY_SEED) {
   176|    const record: IVXMemoryRecord = {
