   188|export function createMemory(input: {
   189|  category: IVXMemoryCategory;
   190|  source: string;
   191|  content: string;
   192|  confidence?: number;
   193|  verified?: boolean;
   194|  expiresAt?: string | null;
   195|  ownerVisible?: boolean;
   196|  tags?: string[];
   197|}): IVXMemoryRecord {
   198|  initializeMemory();
   199|  const now = new Date().toISOString();
   200|  const record: IVXMemoryRecord = {
   201|    id: randomUUID(),
   202|    category: input.category,
   203|    source: input.source,
   204|    content: input.content,
   205|    confidence: input.confidence ?? 0.5,
   206|    verified: input.verified ?? false,
   207|    createdAt: now,
   208|    updatedAt: now,
   209|    expiresAt: input.expiresAt ?? null,
   210|    supersededById: null,
   211|    ownerVisible: input.ownerVisible ?? true,
   212|    tags: input.tags || [],
   213|  };
   214|
   215|  memoryStore.set(record.id, record);
   216|
   217|  // Enforce max size — evict oldest expired session memory
   218|  if (memoryStore.size > MAX_STORE_SIZE) {
   219|    const sessionRecords = [...memoryStore.values()]
   220|      .filter((r) => r.category === 'session')
   221|      .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
   222|    for (const old of sessionRecords) {
   223|      memoryStore.delete(old.id);
   224|      if (memoryStore.size <= MAX_STORE_SIZE) break;
   225|    }
   226|  }
   227|
   228|  return record;
