   236|export function queryMemory(query: IVXMemoryQuery): IVXMemoryRecord[] {
   237|  initializeMemory();
   238|
   239|  let results = [...memoryStore.values()];
   240|
   241|  // Filter expired
   242|  const now = new Date();
   243|  results = results.filter((r) => {
   244|    if (!r.expiresAt) return true;
   245|    return new Date(r.expiresAt) > now;
   246|  });
   247|
   248|  // Filter superseded
   249|  results = results.filter((r) => r.supersededById === null);
   250|
   251|  if (query.category) {
   252|    results = results.filter((r) => r.category === query.category);
   253|  }
   254|
   255|  if (query.verifiedOnly) {
   256|    results = results.filter((r) => r.verified);
   257|  }
   258|
   259|  if (query.minConfidence !== undefined) {
   260|    results = results.filter((r) => r.confidence >= query.minConfidence!);
   261|  }
   262|
   263|  if (query.tags && query.tags.length > 0) {
   264|    results = results.filter((r) => query.tags!.some((t) => r.tags.includes(t)));
   265|  }
   266|
   267|  if (query.search) {
   268|    const search = query.search.toLowerCase();
   269|    results = results.filter((r) => r.content.toLowerCase().includes(search));
   270|  }
   271|
   272|  // Sort by confidence (highest first), then by most recently updated
   273|  results.sort((a, b) => {
   274|    if (a.verified !== b.verified) return a.verified ? -1 : 1;
   275|    if (b.confidence !== a.confidence) return b.confidence - a.confidence;
   276|    return b.updatedAt.localeCompare(a.updatedAt);
   277|  });
   278|
   279|  return results.slice(0, query.limit || 20);
