   282|export function updateMemory(id: string, updates: Partial<IVXMemoryRecord>): IVXMemoryRecord | null {
   283|  initializeMemory();
   284|  const existing = memoryStore.get(id);
   285|  if (!existing) return null;
   286|
   287|  const updated: IVXMemoryRecord = {
   288|    ...existing,
   289|    ...updates,
   290|    id: existing.id, // Prevent ID change
   291|    updatedAt: new Date().toISOString(),
   292|  };
   293|  memoryStore.set(id, updated);
   294|  return updated;
   295|}
