   304|export function executeOwnerControl(control: IVXMemoryOwnerControl, input: {
   305|  id?: string;
   306|  content?: string;
   307|  expiresAt?: string | null;
   308|}): { success: boolean; message: string; record?: IVXMemoryRecord } {
   309|  initializeMemory();
   310|
   311|  switch (control) {
   312|    case 'show': {
   313|      const records = queryMemory({ limit: 50, ownerVisible: true } as IVXMemoryQuery & { ownerVisible: boolean });
   314|      return { success: true, message: `${records.length} memory records found` };
   315|    }
   316|
   317|    case 'correct': {
   318|      if (!input.id || !input.content) {
   319|        return { success: false, message: 'id and content required' };
   320|      }
   321|      const updated = updateMemory(input.id, { content: input.content, verified: false, confidence: 0.5 });
   322|      if (!updated) return { success: false, message: 'Memory record not found' };
   323|      return { success: true, message: 'Memory corrected (marked unverified)', record: updated };
   324|    }
   325|
   326|    case 'delete': {
   327|      if (!input.id) return { success: false, message: 'id required' };
   328|      const deleted = deleteMemory(input.id);
   329|      return { success: deleted, message: deleted ? 'Memory deleted' : 'Memory not found' };
   330|    }
   331|
   332|    case 'mark_permanent': {
   333|      if (!input.id) return { success: false, message: 'id required' };
   334|      const updated = updateMemory(input.id, { expiresAt: null });
   335|      if (!updated) return { success: false, message: 'Memory not found' };
   336|      return { success: true, message: 'Memory marked permanent', record: updated };
   337|    }
   338|
   339|    case 'mark_temporary': {
   340|      if (!input.id) return { success: false, message: 'id required' };
   341|      const expiresAt = input.expiresAt || new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
   342|      const updated = updateMemory(input.id, { expiresAt });
   343|      if (!updated) return { success: false, message: 'Memory not found' };
   344|      return { success: true, message: 'Memory marked temporary', record: updated };
   345|    }
   346|
   347|    default:
   348|      return { success: false, message: 'Unknown control' };
   349|  }
