   197|  // so the final rename is intra-device (avoids EXDEV when os.tmpdir() is on a
   198|  // different filesystem than the project dir). Unique name per write prevents
   199|  // parallel-writer collisions.
   200|  await ensureDir();
   201|  const tmp = path.join(DIR, `ivx-unified-memory-${randomUUID()}.tmp`);
   202|  await writeFile(tmp, JSON.stringify(bounded, null, 2), 'utf8');
   203|  try {
