   134|// ─── Token Budgeting ──────────────────────────────────────────────
   135|
   136|const DEFAULT_TOKEN_BUDGET = 12000;
   137|
   138|function allocateTokenBudget(
   139|  totalBudget: number,
   140|  context: {
   141|    messageCount: number;
   142|    memoryCount: number;
   143|    retrievedCount: number;
   144|    entityCount: number;
