   147|  // Reserve system prompt
   148|  const systemPrompt = 500;
   149|  const remaining = totalBudget - systemPrompt;
   150|
   151|  // Weighted allocation
   152|  const conversationWeight = Math.min(0.4, 0.2 + context.messageCount * 0.03);
   153|  const memoryWeight = Math.min(0.2, 0.05 + context.memoryCount * 0.02);
   154|  const retrievedWeight = Math.min(0.2, 0.05 + context.retrievedCount * 0.02);
   155|  const entityWeight = Math.min(0.15, 0.05 + context.entityCount * 0.02);
   156|  const productionWeight = 0.1;
