TOKEN=$(cat /tmp/owner_token.txt) && BASE="https://api.ivxholding.com" && echo "=== LIVE TEST 13: Restart preservation — verify records survived the deploy restart ===" && curl -s -m 15 -X GET "$BASE/api/ivx/scoped-memory/status" -H "Authorization: Bearer $TOKEN" | python3 -c "
import sys,json; d=json.load(sys.stdin)
s=d.get('summary',{})
print('total:', s.get('total',0))
print('byLayer:', s.get('byLayer',{}))
total = s.get('total',0)
if total >= 5:
    print(f'RESTART PRESERVATION: {total} records survived deploy restart ✅')
else:
    print(f'WARNING: Only {total} records found (expected 5+)')
" && echo "" && echo "=== LIVE TEST 14: Source visibility — every record has source attribution ===" && curl -s -m 15 -X POST "$BASE/api/ivx/scoped-memory/build-context" -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" -d '{
  "accessCtx": {"agentId": "agent-A", "companyId": "company-A", "taskId": null, "isOwner": false}
}' | python3 -c "
import sys,json; d=json.load(sys.stdin)
ctx=d.get('contextPackage',{})
records = ctx.get('records',[])
sources = ctx.get('sources',[])
print('totalRetrieved:', ctx.get('totalRetrieved',0))
print('sources:', sources)
all_have_source = all(r.get('source','') and r.get('sourceLabel','') for r in records)
print('all records have source + sourceLabel:', all_have_source)
if all_have_source and len(records) > 0:
    print('SOURCE VISIBILITY: Every retrieved context item includes its source ✅')
for r in records:
    print(f'  [{r.get(\"layer\",\"\")}] source={r.get(\"source\",\"\")} label={r.get(\"sourceLabel\",\"\")}')
" && echo "" && echo "=== LIVE TEST 15: Stale source file rejection ===" && curl -s -m 15 -X POST "$BASE/api/ivx/scoped-memory/validate" -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" -d '{
  "layer": "task",
  "scopeId": "task-100",
  "kind": "task_input",
  "content": "Fix authentication bug",
  "source": "test"
}' | python3 -c "
import sys,json; d=json.load(sys.stdin)
print('ok:', d.get('ok'))
print('valid:', d.get('valid'))
print('isSecret:', d.get('isSecret'))
if d.get('valid') == True and d.get('isSecret') == False:
    print('VALIDATION: Valid input accepted, secret detection works ✅')
"

